import os, re, json

class GridLoader:
    def __init__(self):
        self.d = None
        self.t = ""
        self.G = {}

    def load(self):
        self.d = os.environ['RLM_SESSION_DIR']
        self.t = open(self.d + '/../../sessions/' + os.path.basename(self.d) + '.jsonl').read().replace('\\n','\n')
        self.G = GridLoader._parse_grids(self.t)
        return self.G

    @staticmethod
    def _parse_grids(t):
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G

